import{_ as i,o as a,c as e,ag as t}from"./chunks/framework.C3EQwh3l.js";const k=JSON.parse('{"title":"Unattended Installation Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"guides/Unattended-Installation.md","filePath":"guides/Unattended-Installation.md"}'),n={name:"guides/Unattended-Installation.md"};function l(o,s,r,p,d,h){return a(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="unattended-installation-architecture" tabindex="-1">Unattended Installation Architecture <a class="header-anchor" href="#unattended-installation-architecture" aria-label="Permalink to &quot;Unattended Installation Architecture&quot;">​</a></h1><p>This document details the zero-touch automated provisioning architecture of <strong>Windows CoreOS (WCOS)</strong> using Microsoft Answer Files (<code>autounattend.xml</code>) and dual-drive ISO injection.</p><hr><h2 id="🚀-dual-drive-unattended-strategy" tabindex="-1">🚀 Dual-Drive Unattended Strategy <a class="header-anchor" href="#🚀-dual-drive-unattended-strategy" aria-label="Permalink to &quot;🚀 Dual-Drive Unattended Strategy&quot;">​</a></h2><p>Standard Windows Setup requires interactive prompts to accept licenses, select partition schemes, format disks, and install drivers. WCOS eliminates all interactive prompts through <strong>dual-drive virtualization</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+-------------------------------------------------------------+</span></span>
<span class="line"><span>| QEMU Virtual Machine                                        |</span></span>
<span class="line"><span>|                                                             |</span></span>
<span class="line"><span>|   Drive 1: windows-core-installer.iso (Read-Only DVD)       |</span></span>
<span class="line"><span>|     - Official unmodified Microsoft OEM ISO                 |</span></span>
<span class="line"><span>|     - Contains install.wim (Server Core build 17763)        |</span></span>
<span class="line"><span>|                                                             |</span></span>
<span class="line"><span>|   Drive 2: oemdrv.iso (Virtual OEM Drive)                   |</span></span>
<span class="line"><span>|     - autounattend.xml                                      |</span></span>
<span class="line"><span>|     - VirtIO storage &amp; network drivers                      |</span></span>
<span class="line"><span>|     - PowerShell 7 runtime MSI                              |</span></span>
<span class="line"><span>|     - C:\\Provisioning scripts &amp; configuration cache         |</span></span>
<span class="line"><span>|                                                             |</span></span>
<span class="line"><span>|   Drive 3: windows-core.qcow2 (VirtIO SCSI Disk)            |</span></span>
<span class="line"><span>|     - Target GPT/UEFI installation target                   |</span></span>
<span class="line"><span>+-------------------------------------------------------------+</span></span></code></pre></div><p>When Windows Setup boots from Drive 1, it automatically scans all connected drives for a file named <code>autounattend.xml</code>. Finding it on Drive 2 (<code>OEMDRV</code>), Setup switches into automated unattended mode without any user intervention.</p><hr><h2 id="📑-unattended-configuration-stages-autounattend-xml" tabindex="-1">📑 Unattended Configuration Stages (<code>autounattend.xml</code>) <a class="header-anchor" href="#📑-unattended-configuration-stages-autounattend-xml" aria-label="Permalink to &quot;📑 Unattended Configuration Stages (\`autounattend.xml\`)&quot;">​</a></h2><p>Windows Setup executes answer file directives across defined configuration passes:</p><h3 id="_1-windowspe-pass-preinstallation-environment" tabindex="-1">1. <code>windowsPE</code> Pass (Preinstallation Environment) <a class="header-anchor" href="#_1-windowspe-pass-preinstallation-environment" aria-label="Permalink to &quot;1. \`windowsPE\` Pass (Preinstallation Environment)&quot;">​</a></h3><ul><li><strong>Hardware Bypasses</strong>: Injects registry flags into the WinPE setup environment to bypass TPM 2.0, SecureBoot, RAM, and CPU compatibility checks:<div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">RunSynchronousCommand</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> wcm:action</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;add&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Order</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;1&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Order</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;reg add HKLM\\SYSTEM\\Setup\\LabConfig /v BypassTPMCheck /t REG_DWORD /d 1 /f&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">RunSynchronousCommand</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">RunSynchronousCommand</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> wcm:action</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;add&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Order</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;2&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Order</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;reg add HKLM\\SYSTEM\\Setup\\LabConfig /v BypassSecureBootCheck /t REG_DWORD /d 1 /f&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">RunSynchronousCommand</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">RunSynchronousCommand</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> wcm:action</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;add&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Order</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;3&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Order</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;reg add HKLM\\SYSTEM\\Setup\\LabConfig /v BypassRAMCheck /t REG_DWORD /d 1 /f&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">RunSynchronousCommand</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div></li><li><strong>VirtIO Driver Injection</strong>: Directs Setup to scan <code>D:\\virtio\\amd64\\2k19</code> (or <code>E:\\</code>) for VirtIO SCSI and Network drivers before initializing the storage controller.</li><li><strong>Disk Partitioning</strong>: Automatically initializes the target disk with a standard UEFI/GPT layout: <ul><li>Partition 1: EFI System Partition (100 MB, FAT32)</li><li>Partition 2: Microsoft Reserved Partition (16 MB, MSR)</li><li>Partition 3: Windows OS Partition (Remaining space, NTFS, labeled <code>WindowsCore</code>)</li></ul></li><li><strong>Image Selection</strong>: Automatically selects the Windows Server Core OEM edition (<code>SERVERHYPERCORE</code>) from <code>install.wim</code>.</li></ul><hr><h3 id="_2-specialize-pass-hardware-network-specialization" tabindex="-1">2. <code>specialize</code> Pass (Hardware &amp; Network Specialization) <a class="header-anchor" href="#_2-specialize-pass-hardware-network-specialization" aria-label="Permalink to &quot;2. \`specialize\` Pass (Hardware &amp; Network Specialization)&quot;">​</a></h3><ul><li><strong>Computer Name</strong>: Sets NetBIOS hostname to <code>windows-core</code>.</li><li><strong>Timezone &amp; Locale</strong>: <ul><li>Timezone: <code>E. South America Standard Time</code> (<code>America/Sao_Paulo</code>, UTC-3).</li><li>UI Language: <code>en-US</code>.</li><li>System Locale &amp; Number Formatting: <code>pt-BR</code>.</li><li>Input Keyboard Layout: <code>0416:00000416</code> (Brazilian ABNT2).</li></ul></li><li><strong>Network Location</strong>: Configures network profile as <code>Private</code> to enable remote management services without aggressive public firewall drop policies.</li><li><strong>Stage 1 Provisioning</strong>: Executes <code>C:\\Provisioning\\scripts\\Specialize.ps1</code>.</li></ul><hr><h3 id="_3-oobesystem-pass-out-of-box-experience-accounts" tabindex="-1">3. <code>oobeSystem</code> Pass (Out-Of-Box Experience &amp; Accounts) <a class="header-anchor" href="#_3-oobesystem-pass-out-of-box-experience-accounts" aria-label="Permalink to &quot;3. \`oobeSystem\` Pass (Out-Of-Box Experience &amp; Accounts)&quot;">​</a></h3><ul><li><strong>User Accounts</strong>: <ul><li><code>samuelcaldas</code>: Primary developer account added to local <code>Administrators</code> group with a non-expiring password.</li><li>Built-in <code>Administrator</code>: AutoLogon enabled for 1 session to complete headless FirstLogon execution.</li></ul></li><li><strong>Privacy &amp; Telemetry Restrictions</strong>: Disables consumer telemetry, Customer Experience Improvement Program (CEIP), error reporting, and Bing search integration.</li></ul><hr><h2 id="🛠️-automated-bootstrap-script-specialize-ps1" tabindex="-1">🛠️ Automated Bootstrap Script (<code>Specialize.ps1</code>) <a class="header-anchor" href="#🛠️-automated-bootstrap-script-specialize-ps1" aria-label="Permalink to &quot;🛠️ Automated Bootstrap Script (\`Specialize.ps1\`)&quot;">​</a></h2><p>During the <code>specialize</code> pass, <code>Specialize.ps1</code> executes under local SYSTEM privileges to configure critical core subsystems:</p><ol><li><strong>PowerShell 7 (<code>pwsh</code>) Installation</strong>: <ul><li>Installs modern PowerShell 7 silently from the offline OEM drive (<code>PowerShell-7.x-win-x64.msi</code>).</li><li>Sets PowerShell execution policy to <code>Unrestricted</code>.</li></ul></li><li><strong>Win32-OpenSSH Server Deployment</strong>: <ul><li>Registers <code>sshd</code> and <code>ssh-agent</code> as automatic Windows services.</li><li>Configures PowerShell 7 as the default shell for all SSH sessions:<div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">New-ItemProperty</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Path </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;HKLM:\\SOFTWARE\\OpenSSH&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Name </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;DefaultShell&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> \`</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Value </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;C:\\Program Files\\PowerShell\\7\\pwsh.exe&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PropertyType String </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Force</span></span></code></pre></div></li></ul></li><li><strong>Hyper-V Role Deactivation</strong>: <ul><li>Because WCOS is a virtual guest on Linux KVM, nested Hyper-V roles and services are decommissioned to prevent CPU/RAM overhead:<div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> bcdedit.exe</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> /</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">set hypervisorlaunchtype off</span></span></code></pre></div></li></ul></li><li><strong>Firewall Rules</strong>: <ul><li>Opens incoming firewall ports for OpenSSH (<code>22</code>), WinRM (<code>5985</code>/<code>5986</code>), and Antigravity Daemon (<code>9090</code>).</li></ul></li><li><strong>Branding Deployment (<code>Deploy-WcosBranding</code>)</strong>: <ul><li>Copies <code>motd.txt</code> to <code>C:\\ProgramData\\ssh\\banner.txt</code>.</li><li>Configures PowerShell 7 profile (<code>profile.ps1</code>) to display the MOTD ASCII banner on terminal start.</li></ul></li></ol>`,22)])])}const g=i(n,[["render",l]]);export{k as __pageData,g as default};
